solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <string>
#include <vector>

struct Caret { float x, y; };
struct Box { float left, top, right, bottom; };

class TextLayout
{
public:
    TextLayout(std::string text, std::vector<float> widths, float maxWidth, float lineHeight)
        : m_text{ std::move(text) }, m_widths{ std::move(widths) }, m_lineHeight{ lineHeight }
    {
        const int n{ static_cast<int>(m_text.size()) };
        m_starts.push_back(0);
        int start{ 0 };
        while (start < n)
        {
            int i{ start }, lastBreak{ -1 };
            bool hardBreak{ false };
            while (i < n)
            {
                const char c{ m_text[static_cast<std::size_t>(i)] };
                if (c == '\n') { ++i; hardBreak = true; break; }
                if (c == ' ') { ++i; lastBreak = i; continue; }       // spaces never make a line too wide
                if (width(start, i) + w(i) > maxWidth && i > start)
                {
                    if (lastBreak > start) i = lastBreak;              // break after the last space
                    break;                                             // or inside a word too long for a line
                }
                ++i;
            }
            if (i >= n && !hardBreak) break;                           // the last line runs to the end
            start = i;
            m_starts.push_back(start);                                 // after a final \n: an empty last line
        }
    }

    int lineCount() const { return static_cast<int>(m_starts.size()); }
    int lineStart(int line) const { return m_starts[static_cast<std::size_t>(line)]; }

    Caret caretAt(int index) const
    {
        const int line{ lineOf(index) };
        return { width(lineStart(line), index), line * m_lineHeight };
    }

    int hitTest(float x, float y) const
    {
        const int line{ std::clamp(static_cast<int>(std::floor(y / m_lineHeight)), 0, lineCount() - 1) };
        const int begin{ lineStart(line) }, end{ caretEnd(line) };
        float pos{ 0 };
        for (int i{ begin }; i < end; ++i)
        {
            const float cw{ w(i) };
            if (x < pos + cw / 2) return i;
            pos += cw;
        }
        return end;
    }

    std::vector<Box> selection(int start, int end) const
    {
        std::vector<Box> out;
        for (int line{ lineOf(start) }; line < lineCount(); ++line)
        {
            const int ls{ lineStart(line) }, le{ lineEnd(line) };
            if (ls >= end && line != lineOf(start)) break;
            const float left{ start > ls ? width(ls, start) : 0.0f };
            const float right{ end < le ? width(ls, end) : width(ls, le) };
            out.push_back({ left, line * m_lineHeight, right, (line + 1) * m_lineHeight });
            if (end <= le) break;
        }
        return out;
    }

private:
    float w(int i) const { return m_text[static_cast<std::size_t>(i)] == '\n' ? 0.0f : m_widths[static_cast<std::size_t>(i)]; }
    float width(int from, int to) const { float s{ 0 }; for (int i{ from }; i < to; ++i) s += w(i); return s; }

    int lineEnd(int line) const { return line + 1 < lineCount() ? lineStart(line + 1) : static_cast<int>(m_text.size()); }

    int caretEnd(int line) const      // where a click past the end of the line puts the caret
    {
        int e{ lineEnd(line) };
        if (line + 1 < lineCount())
        {
            if (e > lineStart(line) && m_text[static_cast<std::size_t>(e - 1)] == '\n') return e - 1;
            while (e > lineStart(line) && m_text[static_cast<std::size_t>(e - 1)] == ' ') --e;
        }
        return e;
    }

    int lineOf(int index) const
    {
        int line{ 0 };
        while (line + 1 < lineCount() && lineStart(line + 1) <= index) ++line;
        return line;
    }

    std::string m_text;
    std::vector<float> m_widths;
    float m_lineHeight;
    std::vector<int> m_starts;
};

unitTests:
std::vector<float> tens(const std::string& s) { return std::vector<float>(s.size(), 10.0f); }
const std::string text = "the quick brown fox";
TEST("wrapping") {
    const TextLayout t{ text, tens(text), 100, 20 };
    CHECK_EQ(t.lineCount(), 2); CHECK_EQ(t.lineStart(1), 10);
    const TextLayout narrow{ text, tens(text), 55, 20 }; CHECK_EQ(narrow.lineCount(), 4); CHECK_EQ(narrow.lineStart(1), 4); CHECK_EQ(narrow.lineStart(2), 10); CHECK_EQ(narrow.lineStart(3), 16);
}
TEST("long words and new lines") {
    const std::string s = "abcdefgh ij"; const TextLayout t{ s, tens(s), 35, 20 }; CHECK_EQ(t.lineCount(), 4); CHECK_EQ(t.lineStart(1), 3); CHECK_EQ(t.lineStart(2), 6); CHECK_EQ(t.lineStart(3), 9);
    const std::string n = "ab\ncd\n"; const TextLayout u{ n, tens(n), 1000, 20 }; CHECK_EQ(u.lineCount(), 3); CHECK_EQ(u.lineStart(1), 3); CHECK_EQ(u.lineStart(2), 6);
}
TEST("carets") {
    const TextLayout t{ text, tens(text), 100, 20 };
    Caret c = t.caretAt(0); CHECK_NEAR(c.x, 0.0, 1e-5); c = t.caretAt(3); CHECK_NEAR(c.x, 30.0, 1e-5); CHECK_NEAR(c.y, 0.0, 1e-5);
    c = t.caretAt(10); CHECK_NEAR(c.x, 0.0, 1e-5); CHECK_NEAR(c.y, 20.0, 1e-5); c = t.caretAt(19); CHECK_NEAR(c.x, 90.0, 1e-5); CHECK_NEAR(c.y, 20.0, 1e-5);
}
TEST("hit testing") {
    const TextLayout t{ text, tens(text), 100, 20 };
    CHECK_EQ(t.hitTest(14, 5), 1); CHECK_EQ(t.hitTest(16, 5), 2); CHECK_EQ(t.hitTest(-50, 5), 0); CHECK_EQ(t.hitTest(500, 5), 9);
    CHECK_EQ(t.hitTest(500, 25), 19); CHECK_EQ(t.hitTest(3, 999), 10); CHECK_EQ(t.hitTest(3, -10), 0);
    const std::string n = "ab\ncd"; const TextLayout u{ n, tens(n), 1000, 20 }; CHECK_EQ(u.hitTest(500, 5), 2); CHECK_EQ(u.hitTest(500, 25), 5);
}
TEST("selection boxes") {
    const TextLayout t{ text, tens(text), 100, 20 };
    auto one = t.selection(4, 9); CHECK_EQ(one.size(), std::size_t{ 1 }); CHECK_NEAR(one[0].left, 40.0, 1e-5); CHECK_NEAR(one[0].right, 90.0, 1e-5);
    auto two = t.selection(4, 13); CHECK_EQ(two.size(), std::size_t{ 2 }); CHECK_NEAR(two[0].right, 100.0, 1e-5); CHECK_NEAR(two[1].left, 0.0, 1e-5); CHECK_NEAR(two[1].right, 30.0, 1e-5); CHECK_NEAR(two[1].top, 20.0, 1e-5);
}

